UPDATE t_p52389855_chess_online_platfor.rating_settings
SET value = 'Рейтинг определяется на основе результатов партий. За победу начисляются баллы, за поражение — снимаются. Ничья дает небольшой бонус обоим игрокам. Ежедневно рейтинг всех игроков снижается на фиксированное значение для стимуляции активной игры. Рейтинг не может опускаться ниже минимального порога — даже при ежедневном снижении. Начисление баллов рейтинга происходит одинаковым образом ко всем типам игры в шахматы (блиц, рапид, классика и др.). Серийный бонус за победы подряд: если игрок выигрывает 3 партии подряд — он получает дополнительный бонус +15 очков. При 5 победах подряд — ещё +25 очков сверх базовых. Серия сбрасывается при поражении или ничьей.'
WHERE key = 'rating_principles';